sp_AssociarFornecedorProduto	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_AssociarFornecedorProduto`(\n\n    IN p_fornecedor_id  INT,\n\n    IN p_produto_id     INT,\n\n    IN p_idEmpresa      INT,\n\n    IN p_precoCompra    DECIMAL(10,2)\n\n)\nBEGIN\n\n    INSERT INTO FornecedorXProduto (fornecedor_id, produto_id, idEmpresa, precoCompra)\n\n    VALUES (p_fornecedor_id, p_produto_id, p_idEmpresa, p_precoCompra)\n\n    ON DUPLICATE KEY UPDATE\n\n        precoCompra = p_precoCompra;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
